import {HOST_API_VERSION} from './types'
import {hostCapabilities, missingCapabilities} from './capabilities'
import {CraftPackageError, MAX_PACKAGE_BYTES} from './validate'

/**
 * The craft registry's `index.json` — generated by `yarn registry publish` in
 * https://github.com/logisky/crafts (its README documents the format).
 */
export interface RegistryIndex {
    schemaVersion: 1
    crafts: RegistryCraft[]
}

export interface RegistryCraft {
    craftId: string
    label: string
    labels?: Record<string, string>
    description?: string
    /** Free text from the package; not verified. */
    publisher?: string
    hasUi: boolean
    /** Names of the AI tools the craft gives Watson. */
    tools: string[]
    /** Hidden from Browse outside a dev build (e.g. the debugger). */
    unlisted?: boolean
    latest: string
    /** Oldest first. */
    versions: RegistryVersion[]
}

export interface RegistryVersion {
    version: string
    hostApi: number
    /** Host capabilities this version needs; absent = none. */
    requires?: string[]
    /** Relative to the registry base URL. */
    url: string
    sha256: string
    size: number
    publishedAt: string
}

/**
 * Where the registry lives: crafts.config.json's `craftRegistry`, unless
 * localStorage `logisheets.craftRegistry` names another base URL — a local
 * build of the registry site, or a private registry.
 */
export function craftRegistryUrl(): string {
    let override: string | null = null
    try {
        override = localStorage.getItem('logisheets.craftRegistry')
    } catch {
        /* storage blocked: use the build's */
    }
    const base =
        override ||
        (typeof __CRAFT_REGISTRY_URL__ !== 'undefined'
            ? __CRAFT_REGISTRY_URL__
            : '')
    return base.replace(/\/+$/, '')
}

export async function fetchRegistryIndex(
    signal?: AbortSignal
): Promise<RegistryIndex> {
    const base = craftRegistryUrl()
    if (!base) throw new CraftPackageError('registryUnavailable')
    let res: Response
    try {
        // `no-cache` revalidates: Pages caches for minutes, and a stale index
        // would hide a version that was just published.
        res = await fetch(`${base}/index.json`, {signal, cache: 'no-cache'})
    } catch (e) {
        if (signal?.aborted) throw e
        throw new CraftPackageError('registryUnavailable')
    }
    if (!res.ok) throw new CraftPackageError('registryUnavailable')
    const index = (await res.json()) as RegistryIndex
    if (index?.schemaVersion !== 1 || !Array.isArray(index.crafts))
        throw new CraftPackageError('registryUnavailable')
    return index
}

function runsHere(v: RegistryVersion, provided: ReadonlySet<string>): boolean {
    return (
        (v.hostApi ?? 1) <= HOST_API_VERSION &&
        missingCapabilities(v.requires, provided).length === 0
    )
}

/**
 * The newest version this host can run — `hostApi` ≤ HOST_API_VERSION and
 * every `requires` capability provided — or undefined if there is none.
 */
export function pickVersion(
    craft: RegistryCraft,
    provided: ReadonlySet<string> = hostCapabilities()
): RegistryVersion | undefined {
    for (let i = craft.versions.length - 1; i >= 0; i--) {
        const v = craft.versions[i]
        if (runsHere(v, provided)) return v
    }
    return undefined
}

/**
 * Why no version of `craft` runs here, judged by its newest version: it needs
 * capabilities this host lacks (`missing`), or a newer app (`hostApi`).
 * Undefined when some version runs.
 */
export function unavailableReason(
    craft: RegistryCraft,
    provided: ReadonlySet<string> = hostCapabilities()
): {missing: string[]} | {hostApi: number} | undefined {
    if (pickVersion(craft, provided)) return undefined
    const newest = craft.versions[craft.versions.length - 1]
    if (!newest) return undefined
    const missing = missingCapabilities(newest.requires, provided)
    return missing.length ? {missing} : {hostApi: newest.hostApi ?? 1}
}

/**
 * Download one version and check it against the sha256 the index records. The
 * index is what was reviewed and published, so this is what makes the host
 * the files come from irrelevant: bytes that do not match are refused.
 */
export async function downloadRegistryPackage(
    v: RegistryVersion,
    signal?: AbortSignal
): Promise<Uint8Array> {
    if (v.size > MAX_PACKAGE_BYTES)
        throw new CraftPackageError('tooLarge', {
            limitMb: MAX_PACKAGE_BYTES / 1024 / 1024,
        })
    const url = new URL(v.url, `${craftRegistryUrl()}/`).toString()
    let res: Response
    try {
        res = await fetch(url, {signal})
    } catch (e) {
        if (signal?.aborted) throw e
        throw new CraftPackageError('download', {url})
    }
    if (!res.ok) throw new CraftPackageError('download', {url})
    const bytes = new Uint8Array(await res.arrayBuffer())
    const digest = new Uint8Array(
        await crypto.subtle.digest('SHA-256', bytes as BufferSource)
    )
    const hex = [...digest].map((b) => b.toString(16).padStart(2, '0')).join('')
    if (hex !== v.sha256) throw new CraftPackageError('checksum', {url})
    return bytes
}

/** Dotted numeric compare; a non-numeric part compares as text. */
export function compareVersions(a: string, b: string): number {
    const pa = a.split(/[.+-]/)
    const pb = b.split(/[.+-]/)
    for (let i = 0; i < Math.max(pa.length, pb.length); i++) {
        const x = pa[i] ?? '0'
        const y = pb[i] ?? '0'
        const nx = Number(x)
        const ny = Number(y)
        const c =
            Number.isNaN(nx) || Number.isNaN(ny) ? x.localeCompare(y) : nx - ny
        if (c !== 0) return c
    }
    return 0
}
